def solve_W(F, max_S):
    W = {F}
    changed = True
    while changed:
        changed = False
        for x in range(1, max_S + 1):
            if x in W:
                continue
            divs = []
            for i in range(1, int(x**0.5) + 1):
                if x % i == 0:
                    divs.append(i)
                    if i*i != x:
                        divs.append(x // i)
            multiples = []
            # We only need to check multiples up to some reasonable limit.
            # If x is large, a multiple d = x*k would mean d-1 and d+1 
            # are large. This doesn't seem to help unless d-1 and d+1 
            # are already in W.
            # But W only contains F and numbers that can reach F.
            # So d-1 and d+1 must be "small".
            # Thus, d must be small. If d is small, then x must be a 
            # divisor of d.
            # So we only need to check d that are small.
            # What is the maximum d we need to check?
            # If d-1 and d+1 are in W, and W contains numbers <= max_S,
            # then d <= max_S + 1.
            for d in range(2, max_S + 2):
                if x % d == 0 or d % x == 0:
                    if (d-1 in W and d+1 in W) or (d-1 == F and d+1 in W) or (d+1 == F and d-1 in W):
                        W.add(x)
                        changed = True
                        break
    return W

