def solve_W(F, max_S):
    W = {F}
    changed = True
    while changed:
        changed = False
        for x in range(1, max_S + 1):
            if x in W:
                continue
            divs = []
            for i in range(1, int(x**0.5) + 1):
                if x % i == 0:
                    divs.append(i)
                    if i*i != x:
                        divs.append(x // i)
            multiples = []
            for d in range(1, max_S + 2):
                if d % x == 0:
                    multiples.append(d)

            all_d = [d for d in divs if d > 1] + [m for m in multiples if m > 1]
            for d in all_d:
                if (d-1 in W and d+1 in W) or (d-1 == F and d+1 in W) or (d+1 == F and d-1 in W):
                    W.add(x)
                    changed = True
                    break
    return W

